-- pgCK v3.11 - PURIFIED INSTALL, collapsed from the 32-chunk molding sequence.
--
-- GENERATED by CK-org from the chain-built reference install. Not hand-written.
-- One definition per object, replacing a 0.2.2 bootstrap plus twenty-nine accreted
-- deltas replayed on every fresh install.
--
-- WHY, not preference: pgCK measured that the chain is not an upgrade path and
-- cannot be made one. pgck--0.3.1--0.3.2.sql and pgck--0.4.0--0.4.1.sql do not
-- exist, and pgck--0.4.1--0.4.2.sql loads after 0.4.20--0.4.21, working only
-- because those statements happen to be commutative today. Nothing enforces that
-- and nothing would report it.
--
-- NAMESPACE: re-pointed v3.8 -> v3.11 here. The collapsed form carries it 0
-- times, against 26 in the source chain, because each object is defined once
-- instead of being redefined across deltas.
--
-- CONTENTS: 12 tables, 70 constraints, 2 indexes, 80 routines (75 that the
-- extension owns today plus the 5 currently loose - see below).
--
-- MEASURED WHILE GENERATING THIS, and it corroborates pgCK's PASS-13 report from
-- a different direction: pg_dump skips extension members, and it emitted exactly
-- five ckp functions - _body_to_ttl(3-arg), _composed_shapes, _parent_closure_ttl,
-- _report_summary, validation_report_ttl. Those five are in the schema and NOT
-- owned by the extension. boot and seal ARE owned, because the in-session apply
-- used CREATE OR REPLACE on functions that already existed. On a fresh install
-- from the shipped .so, boot and seal are the OLD versions and the five are absent.
--
-- PROOF OBLIGATION - pgCK's own, attached and non-optional:
--   fnset.sql                 the harness
--   fnset.chain-built.txt     80 routines, baseline 062a49ad1ad76d81
--   fnset.purified.txt        produced from a fresh install of THIS file
-- Diff the two. Identical means nothing was lost; one differing line names the routine.
--
-- REVIEW, DO NOT MERGE BLIND. A generated starting point for pgCK, whose repo and
-- whose call. CK-org touched nothing inside it.

-- Routines are emitted in a flat order and reference each other freely.
-- SQL-language bodies are validated at CREATE time, so a forward reference
-- fails without this. pg_dump emits the same line for the same reason; it is
-- restore hygiene, not a relaxation of anything the extension enforces.
SET check_function_bodies = false;

CREATE SCHEMA IF NOT EXISTS ckp;

-- ==================== ROLES ====================
-- AMENDED IN pgCK (#48), not part of the CK-org generation: the generator's
-- proof obligation was function-set parity, and roles are not functions, so
-- the retired chain's role lifecycle (pgck--0.2.2--0.2.3.sql CREATE ROLE,
-- pgck--0.2.5--0.2.6.sql ALTER ... LOGIN) was structurally invisible to it.
-- Every warm cluster carries these roles from history — roles are
-- cluster-level and survive DROP EXTENSION — so only a virgin cluster ever
-- reached the first OWNER TO below without them (s34's exact contract).
-- Chain end-state, create-if-missing; a pre-existing role is never mutated
-- (an operator's configuration outranks a replay).
DO $ck_roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ck_substrate') THEN
    CREATE ROLE ck_substrate NOLOGIN;
    COMMENT ON ROLE ck_substrate IS
      'pgCK Ring-1 owner; the ONLY role granted pgrdf.* and the ckp internals (CKP v3.9 §7 / CI-A-4). Non-login.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ck_participant') THEN
    CREATE ROLE ck_participant LOGIN;
    COMMENT ON ROLE ck_participant IS
      'The only role connections/agents receive; granted EXACTLY ckp.dispatch (CKP v3.9 §7). LOGIN so it can be connected-as; no password here — auth is the deployment''s concern.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ck_drainer') THEN
    CREATE ROLE ck_drainer LOGIN;
    COMMENT ON ROLE ck_drainer IS
      'The outbox drain connection role; schema USAGE on ckp plus what the floor pass grants — nothing else.';
  END IF;
END
$ck_roles$;

